<script lang="ts">import type { MasonryLayoutDetail,MasonryPlacement } from '@fex-design/svelte/primitive/masonry';import { MasonryItem,MasonryRoot,MasonryViewport } from '@fex-design/svelte/primitive/masonry';import { masonryItems } from './data';const items=masonryItems.slice(0,9);let ordered:Record<string,number>=$state({}),shortest:Record<string,number>=$state({});const cols=(value:MasonryLayoutDetail)=>Object.fromEntries(value.items.map(item=>[String(item.key),item.column+1]))</script>
{#snippet example(placement:MasonryPlacement)}{@const columns=placement==='ordered'?ordered:shortest}<section class="grid gap-space-sm"><div><h3 class="font-medium">{placement==='ordered'?'按输入顺序（ordered）':'按当前最短列（shortest）'}</h3><p class="text-sm text-muted-foreground">{placement==='ordered'?'按第 1、2、3 列循环分配，视觉读取顺序更稳定。':'每次进入累计高度最小的列，列高更均衡。'}</p></div><MasonryRoot columns={3} gap={12} {placement} onLayoutChange={value=>placement==='ordered'?ordered=cols(value):shortest=cols(value)}><MasonryViewport>{#each items as item,index(item.id)}<MasonryItem itemKey={item.id} {index}><div class="rounded-md border border-border bg-muted-background p-space-sm" style:height={`${item.height/2}px`}><strong>Card {index+1}</strong><p class="text-xs text-muted-foreground">输入序号 {index+1} · 最终第 {columns[item.id]??'…'} 列</p></div></MasonryItem>{/each}</MasonryViewport></MasonryRoot></section>{/snippet}
<div class="grid gap-space-xl">{@render example('ordered')}{@render example('shortest')}<section class="grid gap-space-sm"><h3 class="font-medium">指定列与自动分配混排</h3><MasonryRoot columns={{minColumnWidth:160,max:3}} gap={12}><MasonryViewport>{#each items.slice(0,6) as item,index(item.id)}<MasonryItem itemKey={item.id} {index} column={index===1?2:undefined}><div class="rounded-md border border-border bg-muted-background p-space-sm" style:height={`${item.height/2}px`}>Card {index+1} · {index===1?'固定第 3 列':'自动最短列'}</div></MasonryItem>{/each}</MasonryViewport></MasonryRoot></section></div>
